CREATE VIEW [indiana_tax].[vwValuationComps]
AS
SELECT
    v.*,
    indianataxSaleTransaction_SaleTransactionID.[SitusAddress] AS [SaleTransaction],
    indianataxSourceDocument_SourceDocumentID.[Title] AS [SourceDocument],
    ${flyway:defaultSchema}_rgc.[Latitude] AS [${flyway:defaultSchema}_Latitude],
    ${flyway:defaultSchema}_rgc.[Longitude] AS [${flyway:defaultSchema}_Longitude]
FROM
    [indiana_tax].[ValuationComp] AS v
LEFT OUTER JOIN
    [indiana_tax].[SaleTransaction] AS indianataxSaleTransaction_SaleTransactionID
  ON
    [v].[SaleTransactionID] = indianataxSaleTransaction_SaleTransactionID.[ID]
LEFT OUTER JOIN
    [indiana_tax].[SourceDocument] AS indianataxSourceDocument_SourceDocumentID
  ON
    [v].[SourceDocumentID] = indianataxSourceDocument_SourceDocumentID.[ID]
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[vwRecordGeoCodes] AS ${flyway:defaultSchema}_rgc
  ON
    ${flyway:defaultSchema}_rgc.[EntityID] = '20711874-0B68-4C10-AE79-77B6A5479B87'
    AND ${flyway:defaultSchema}_rgc.[RecordID] = CAST([v].[ID] AS NVARCHAR(450))
