CREATE VIEW [indiana_tax].[vwAssessmentNotices]
AS
SELECT
    a.*,
    indianataxSourceDocument_SourceDocumentID.[Title] AS [SourceDocument],
    indianataxParcel_ParcelID.[ParcelNumber] AS [Parcel],
    ${flyway:defaultSchema}_rgc.[Latitude] AS [${flyway:defaultSchema}_Latitude],
    ${flyway:defaultSchema}_rgc.[Longitude] AS [${flyway:defaultSchema}_Longitude]
FROM
    [indiana_tax].[AssessmentNotice] AS a
INNER JOIN
    [indiana_tax].[SourceDocument] AS indianataxSourceDocument_SourceDocumentID
  ON
    [a].[SourceDocumentID] = indianataxSourceDocument_SourceDocumentID.[ID]
INNER JOIN
    [indiana_tax].[Parcel] AS indianataxParcel_ParcelID
  ON
    [a].[ParcelID] = indianataxParcel_ParcelID.[ID]
LEFT OUTER JOIN
    [${flyway:defaultSchema}].[vwRecordGeoCodes] AS ${flyway:defaultSchema}_rgc
  ON
    ${flyway:defaultSchema}_rgc.[EntityID] = '3A750BC9-0034-47FE-BD90-AA41E6EBACEB'
